            Q('v2', L('Perché “perché questo codice è sicuro?” è una cattiva domanda?', 'Why is “why is this code secure?” a bad question?'), [L('Spinge il modello a difendere il codice', 'It pushes the model to defend the code'), L('È troppo breve per essere capita', 'It is too short to be understood'), L('I modelli non leggono il codice', 'Models do not read code'), L('Contiene una parola vietata', 'It contains a forbidden word')], 0, L('Suggerisce già la risposta.', 'It already suggests the answer.')),
            Q('v3', L('Quale richiesta aiuta a scoprire errori nella risposta?', 'Which request helps uncover mistakes in the answer?'), [L('“Rispondi con sicurezza, senza dubbi”', '“Answer confidently, without doubts”'), L('“Elenca i punti in cui non sei sicuro”', '“List the points you are unsure about”'), L('“Scrivi la risposta il più in fretta possibile”', '“Write the answer as fast as possible”'), L('“Non ammettere mai di non sapere”', '“Never admit you do not know”')], 1, L('L’incertezza dichiarata si può controllare.', 'Declared uncertainty can be checked.')),
        ], task('text', L('Riscrivi in modo neutro la domanda “Perché il mio piano di marketing è ottimo?”, chiedendo punti deboli e lasciando la possibilità di non trovarne.', 'Rewrite neutrally the question “Why is my marketing plan excellent?”, asking for weak points and allowing for finding none.'), 'Perché il mio piano di marketing è ottimo?', [re('piano|plan', L('Parli ancora del piano', 'You still talk about the plan')), re('debol|problem|rischi|difett|weak|risk|flaw|critic', L('Chiedi i punti deboli', 'You ask for weak points')), re('non ne trovi|nessun|se non (ce ne sono|ne trovi)|none|no (issues|problems)|if there are none|find none', L('Lasci la possibilità di non trovarne', 'You allow for finding none'))], '', 'Quali sono i punti deboli e i rischi del mio piano di marketing? Elencali, oppure scrivi che non ne trovi.'), [
